// Serveur TOEIC Arena : fichiers statiques + relais de "présence" par salle (SSE + POST). Aucune dépendance.
const http=require("http"),fs=require("fs"),path=require("path");
const PORT=process.env.PORT||3000,PUB=path.join(__dirname,"public"),rooms=new Map(),HTML=Buffer.from("","base64").toString("utf8");
const LOGO='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#2f6fed"/><stop offset="1" stop-color="#c026d3"/></linearGradient></defs><rect width="64" height="64" rx="16" fill="url(#g)"/><path d="M14 20h36v6H35v22h-6V26H14z" fill="#fff"/><path d="M47 6l2.6 5.2 5.8.8-4.2 4.1 1 5.8-5.2-2.7-5.2 2.7 1-5.8-4.2-4.1 5.8-.8z" fill="#ffc83d"/></svg>';
const MIME={".html":"text/html; charset=utf-8",".js":"text/javascript; charset=utf-8",".css":"text/css; charset=utf-8",".json":"application/json",".png":"image/png",".svg":"image/svg+xml"};
function bcast(name){const r=rooms.get(name);if(!r)return;
 const msg="data:"+JSON.stringify([...r].map(([id,p])=>({id,presence:p.presence})))+"\n\n";
 for(const p of r.values())p.res.write(msg)}

const crypto=require("crypto"),UR=process.env.UPSTASH_REDIS_REST_URL,UT=process.env.UPSTASH_REDIS_REST_TOKEN,fails=new Map();
const rd=async c=>{const r=await fetch(UR,{method:"POST",headers:{Authorization:"Bearer "+UT,"Content-Type":"application/json"},body:JSON.stringify(c)});const j=await r.json();if(j.error)throw new Error(j.error);return j.result};
const hp=(code,salt)=>crypto.scryptSync(code,salt,32).toString("hex");
function api(req,res,u){
 const out=(c,o)=>{res.writeHead(c,{"Content-Type":"application/json"});res.end(JSON.stringify(o))};
 if(!UR||!UT)return out(503,{err:"Les comptes ne sont pas encore configurés sur ce serveur."});
 let b="";req.on("data",c=>{b+=c;if(b.length>80000)req.destroy()});
 req.on("end",async()=>{try{
  const d=JSON.parse(b||"{}"),em=String(d.email||"").trim().toLowerCase();
  if(u.pathname==="/api/signup"||u.pathname==="/api/login"){
   if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)||em.length>120)return out(400,{err:"Adresse e-mail invalide."});
   const code=String(d.code||"");if(code.length<6||code.length>64)return out(400,{err:"Le code doit faire au moins 6 caractères."});
   const fk=em+"|"+(req.headers["x-forwarded-for"]||req.socket.remoteAddress),now=Date.now(),rec=(fails.get(fk)||[]).filter(t=>now-t<6e5);
   if(rec.length>=8)return out(429,{err:"Trop d’essais, réessaie dans 10 minutes."});
   const cur=await rd(["GET","acct:"+em]),acc=cur?JSON.parse(cur):null;let prof=null;
   if(u.pathname==="/api/signup"){
    if(acc)return out(409,{err:"Un compte existe déjà avec cet e-mail : connecte-toi."});
    const salt=crypto.randomBytes(16).toString("hex");
    await rd(["SET","acct:"+em,JSON.stringify({salt,h:hp(code,salt),p:typeof d.profile==="object"?d.profile:null})]);
   }else{
    if(!acc||hp(code,acc.salt)!==acc.h){rec.push(now);fails.set(fk,rec);return out(401,{err:"E-mail ou code incorrect."})}
    prof=acc.p;
   }
   const tok=crypto.randomBytes(24).toString("hex");
   await rd(["SET","tok:"+tok,em,"EX",2592000]);
   return out(200,{token:tok,email:em,profile:prof});
  }
  const who=await rd(["GET","tok:"+String(d.token||"")]);
  if(!who)return out(401,{err:"Session expirée, reconnecte-toi."});
  const acc=JSON.parse(await rd(["GET","acct:"+who]));
  if(u.pathname==="/api/save"){if(typeof d.profile==="object"&&d.profile){acc.p=d.profile;await mine(who,acc);await rd(["SET","acct:"+who,JSON.stringify(acc)]);await rd(["SET","pub:"+acc.uid,JSON.stringify(pubOf(acc.uid,acc.p,who))])}return out(200,{ok:1})}
  if(u.pathname==="/api/profile")return out(200,{email:who,profile:acc.p});
  if(u.pathname==="/api/soc")return soc(d,who,acc,out);
  out(404,{err:"Introuvable"});
 }catch(e){out(500,{err:"Erreur serveur."})}});
}

// ---- Social : amis, profils publics, classement (Upstash) ----
const eh=em=>crypto.createHash("sha256").update(String(em)).digest("hex").slice(0,12);
const uidFor=em=>{const x=crypto.createHash("sha256").update("uid:"+em).digest(),A="ABCDEFGHJKMNPQRSTUVWXYZ23456789";return Array.from({length:6},(_,i)=>A[x[i]%31]).join("")};
const pubOf=(uid,p,em)=>{p=p||{};const bp=p.byP&&typeof p.byP==="object"?p.byP:{},t=Object.values(bp).reduce((s,a)=>[s[0]+(a[0]|0),s[1]+(a[1]|0)],[0,0]);return{uid,o:eh(em),nm:String(p.nm||"Joueur").slice(0,14),av:p.av|0,xp:p.xp|0,lv:Math.floor(Math.sqrt((p.xp|0)/60))+1,nc:Object.keys(p.cards||{}).length,tq:t[0],ok:t[1],bp,best:p.best|0,games:p.games|0,tg:p.tg|0,es:p.es|0}};
const mine=async(who,acc)=>{if(!acc.uid){acc.uid=uidFor(who);await rd(["SET","acct:"+who,JSON.stringify(acc)]);await rd(["SADD","users",acc.uid])}return acc.uid};
const pubs=async ids=>ids.length?(await rd(["MGET",...ids.map(i=>"pub:"+i)])).filter(Boolean).map(x=>JSON.parse(x)):[];
const light=p=>({uid:p.uid,nm:p.nm,av:p.av,lv:p.lv,tq:p.tq,ok:p.ok});
async function repair(){
 const keys=await rd(["KEYS","acct:*"]),ok=new Map();
 for(const k of keys){const raw=await rd(["GET",k]);if(!raw)continue;const a=JSON.parse(raw),em=k.slice(5);if(!a.uid){a.uid=uidFor(em);await rd(["SET",k,JSON.stringify(a)])}ok.set(a.uid,{em,a})}
 for(const u of await rd(["SMEMBERS","users"]))if(!ok.has(u)){await rd(["SREM","users",u]);for(const x of["pub:","fr:","rq:","rm:"])await rd(["DEL",x+u])}
 for(const [u,{em,a}] of ok){await rd(["SADD","users",u]);await rd(["SET","pub:"+u,JSON.stringify(pubOf(u,a.p,em))]);
  for(const x of["fr:","rq:"])for(const mb of await rd(["SMEMBERS",x+u]))if(mb===u||!ok.has(mb))await rd(["SREM",x+u,mb])}
 console.log("Réparation sociale :",ok.size,"comptes")
}
if(UR&&UT)setTimeout(()=>repair().catch(e=>console.log("repair:",e.message)),1500);
async function soc(d,who,acc,out){
 const me=await mine(who,acc),myo=eh(who),a=d.act,t=String(d.t||"").toUpperCase(),okT=/^[A-Z0-9]{6}$/.test(t);
 const mp=await rd(["GET","pub:"+me]);if(!mp||!JSON.parse(mp).o)await rd(["SET","pub:"+me,JSON.stringify(pubOf(me,acc.p,who))]);
 const isF=async x=>!!(await rd(["SISMEMBER","fr:"+me,x])),link=async x=>{await rd(["SREM","rq:"+me,x]);await rd(["SADD","fr:"+me,x]);await rd(["SADD","fr:"+x,me])};
 if(a==="list"){const f=await rd(["SMEMBERS","fr:"+me]),q=await rd(["SMEMBERS","rq:"+me]),fp=await pubs(f),rm=f.length?await rd(["MGET",...f.map(i=>"rm:"+i)]):[];
  return out(200,{uid:me,fr:fp.map(p=>({...light(p),room:rm[f.indexOf(p.uid)]?JSON.parse(rm[f.indexOf(p.uid)]):null})),rq:(await pubs(q)).map(light)})}
 if(a==="search"){const q=String(d.q||"").trim().toLowerCase();if(q.length<2)return out(200,{res:[]});
  const all=await pubs(await rd(["SMEMBERS","users"]));return out(200,{res:all.filter(p=>p.uid!==me&&p.o!==myo&&(p.nm.toLowerCase().includes(q)||p.uid.toLowerCase()===q)).slice(0,10).map(light)})}
 if(a==="add"){const tp=okT?await rd(["GET","pub:"+t]):null;if(!tp||t===me||JSON.parse(tp).o===myo)return out(400,{err:"Tu ne peux pas t’ajouter toi-même."});
  if(await isF(t))return out(200,{state:"friends"});
  if(await rd(["SISMEMBER","rq:"+me,t])){await link(t);return out(200,{state:"friends"})}
  await rd(["SADD","rq:"+t,me]);return out(200,{state:"sent"})}
 if(a==="accept"){if(!okT||!await rd(["SISMEMBER","rq:"+me,t]))return out(400,{err:"Demande introuvable."});await link(t);return out(200,{ok:1})}
 if(a==="decline"){if(okT)await rd(["SREM","rq:"+me,t]);return out(200,{ok:1})}
 if(a==="remove"){if(okT){await rd(["SREM","fr:"+me,t]);await rd(["SREM","fr:"+t,me])}return out(200,{ok:1})}
 if(a==="room"){if(d.c)await rd(["SET","rm:"+me,JSON.stringify({c:String(d.c).slice(0,4).toUpperCase(),m:d.m==="duel"?"duel":"speed"}),"EX",1800]);else await rd(["DEL","rm:"+me]);return out(200,{ok:1})}
 if(a==="prof"){const r=okT&&await rd(["GET","pub:"+t]);if(!r)return out(404,{err:"Joueur introuvable."});
  const fr=await isF(t),rm=fr?await rd(["GET","rm:"+t]):null;return out(200,{p:JSON.parse(r),friend:fr,room:rm?JSON.parse(rm):null})}
 if(a==="board"){const by=String(d.by||"acc");let ids=await rd(["SMEMBERS","users"]);if(d.sc==="fr")ids=[me,...await rd(["SMEMBERS","fr:"+me])];
  const pc=(n,o)=>Math.round(1000*o/n)/10,rows=(await pubs(ids)).map(p=>{let v=null,tx,sub="";
   if(by==="acc"&&p.tq>=10){v=pc(p.tq,p.ok);tx=v+" %";sub=p.tq+" questions"}
   else if(["1","2","3","4","5","6","7a","7b"].includes(by)){const x=p.bp[by]||[0,0];if(x[0]>=5){v=pc(x[0],x[1]);tx=v+" %";sub=x[0]+" questions"}}
   else if(by==="nc"){v=p.nc;tx=p.nc+(p.nc>1?" cartes":" carte")}else if(by==="es"){if(p.es){v=p.es;tx=p.es+" / 990";sub="objectif "+(p.tg||"–")}}else if(by==="xp"){v=p.xp;tx="Niv. "+p.lv;sub=p.xp+" XP"}
   return v===null?null:{uid:p.uid,o:p.o,nm:p.nm,av:p.av,lv:p.lv,v,t:tx,s:sub,me:p.uid===me||p.o===myo}}).filter(Boolean).sort((x,y)=>y.v-x.v).filter((r,i,a)=>!r.o||a.findIndex(x=>x.o===r.o)===i);
  return out(200,{rows:rows.slice(0,30),my:rows.findIndex(r=>r.me)+1,total:rows.length})}
 out(404,{err:"Action inconnue."});
}
http.createServer((req,res)=>{
 const u=new URL(req.url,"http://x");
 const room=(u.searchParams.get("room")||"").replace(/[^a-z0-9_-]/g,"").slice(0,32);
 const id=(u.searchParams.get("id")||"").replace(/[^a-z0-9]/gi,"").slice(0,24);
 if(u.pathname==="/events"&&room&&id){
  let r=rooms.get(room);if(!r)rooms.set(room,r=new Map());
  if(r.size>=16&&!r.has(id)){res.writeHead(429);return res.end()}
  res.writeHead(200,{"Content-Type":"text/event-stream","Cache-Control":"no-cache, no-transform","Connection":"keep-alive","X-Accel-Buffering":"no"});
  res.write("retry: 2000\n\n");
  r.set(id,{presence:{},res});bcast(room);
  const ka=setInterval(()=>res.write(":k\n\n"),20000);
  req.on("close",()=>{clearInterval(ka);if(r.get(id)&&r.get(id).res===res)r.delete(id);if(r.size)bcast(room);else rooms.delete(room)});
  return}
 if(u.pathname==="/presence"&&req.method==="POST"&&room&&id){
  let b="";req.on("data",c=>{b+=c;if(b.length>8192)req.destroy()});
  req.on("end",()=>{try{const p=rooms.get(room)&&rooms.get(room).get(id);
   if(p){const patch=JSON.parse(b);for(const k of Object.keys(patch)){if(k==="__proto__"||!/^[A-Za-z_]\w{0,15}$/.test(k))continue;
    if(patch[k]===null)delete p.presence[k];else p.presence[k]=patch[k]}bcast(room)}}catch(e){}
   res.writeHead(204);res.end()});return}
 if(u.pathname.startsWith("/api/")&&req.method==="POST")return api(req,res,u);
 if(u.pathname==="/logo.svg"){res.writeHead(200,{"Content-Type":"image/svg+xml","Cache-Control":"public, max-age=86400"});return res.end(LOGO)}
 if(u.pathname==="/"||u.pathname==="/index.html"){res.writeHead(200,{"Content-Type":"text/html; charset=utf-8"});return res.end(HTML)}
 res.writeHead(404);res.end("Introuvable");
}).listen(PORT,()=>console.log("TOEIC Arena sur http://localhost:"+PORT));
